1	use std::env;
2	use std::ffi::{OsStr, OsString};
3	use std::fs;
4	use std::io::Read;
5	use std::path::Path;
6	use std::process::ExitCode;
7	
8	use roottrace::{
9	    claims_json, hex, hex_nibble, inspect_proof, is_lower_hex, proof_json, root_and_path,
10	    split_records, RootStream,
11	};
12	
13	const VERSION: &str = "0.1.0";
14	
15	const USAGE: &str = "\
16	Usage:
17	    roottrace root <file>
18	    roottrace prove <file> <record-index>
19	    roottrace inspect <proof-file>
20	    roottrace verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
21	    roottrace --version
22	
23	Commands:
24	    root <file>
25	        Print the SHA-256 RFC 6962 Merkle Tree Hash of all records in <file>
26	        as one line of 64 lowercase hexadecimal characters.
27	
28	    prove <file> <record-index>
29	        Print the RFC 6962 section 2.1.1 inclusion (membership) proof for the
30	        record at <record-index> within the whole batch. The index is
31	        0-based and counts records in file order: 0 is the first record,
32	        1 the second, and so on; the same content at multiple positions gets
33	        the proof for the exact position given, with no deduplication. Output
34	        is one JSON object with the fields tree_size, leaf_index, root and
35	        audit_path (leaf-to-root hashes, lowercase hex; empty for a batch of
36	        exactly one record).
37	
38	        Example:
39	            roottrace prove batch.txt 0
40	
41	    inspect <proof-file>
42	        Read one inclusion proof and display the batch size, record position
43	        and root the proof itself claims, without needing the target record
44	        or any independently trusted values. Output is one JSON object with
45	        only the fields tree_size, leaf_index and root. This does NOT verify
46	        membership: the displayed values come from the proof itself, are not
47	        checked against anything, and must not be reused as the trusted
48	        tree size/root arguments of `verify`. A well-formed proof whose
49	        audit_path cannot establish the claimed position is still displayed.
50	
51	        Example:
52	            roottrace inspect proof.json
53	
54	    verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
55	        Verify an inclusion proof produced by `prove` without needing the
56	        whole batch. The record file holds the raw bytes of exactly one
57	        target record (no LF splitting, byte for byte including any trailing
58	        LF/space/CR, NUL and non-UTF-8 bytes; an empty file is one empty
59	        record). The proof is read as one complete JSON object. The trusted
60	        tree size (an ASCII decimal positive integer) and the trusted root
61	        (64 lowercase hexadecimal characters) must be confirmed
62	        independently; they are never taken from fields inside the proof.
63	        On success stdout is exactly \"verified\\n\", stderr is empty and the
64	        exit status is 0.
65	
66	        Example:
67	            roottrace verify record.bin proof.json 9 a8a3e76e...723adc3
68	
69	Exit status:
70	    0  success
71	    1  an input file cannot be read, the proof is malformed, or verification fails
72	    2  usage error (unknown command, missing or extra arguments, bad arguments)";
73	
74	fn main() -> ExitCode {
75	    // Raw OS arguments: file paths are handed to the filesystem exactly as
76	    // received, byte for byte. On Unix a path may contain bytes that are not
77	    // valid UTF-8 (e.g. 0xff); such a path is not invalid and must reach the
78	    // file rather than aborting argument collection. The command name, the
79	    // record index and the trusted tree size/root arguments are required to
80	    // be UTF-8 text.
81	    let args: Vec<OsString> = env::args_os().skip(1).collect();
82	    match args.as_slice() {
83	        [flag] if flag == OsStr::new("--version") => {
84	            println!("roottrace {VERSION}");
85	            ExitCode::SUCCESS
86	        }
87	        [cmd, path] if cmd == OsStr::new("root") => match merkle_root_of_file(Path::new(path)) {
88	            Ok(root) => {
89	                println!("{}", hex(&root));
90	                ExitCode::SUCCESS
91	            }
92	            Err(reason) => {
93	                eprintln!("roottrace: {reason}");
94	                ExitCode::FAILURE
95	            }
96	        },
97	        [cmd, path, index] if cmd == OsStr::new("prove") => match parse_index(index) {
98	            Some(index) => match proof_for_file(Path::new(path), index) {
99	                Ok(proof) => {
100	                    println!("{}", proof);
101	                    ExitCode::SUCCESS
102	                }
103	                Err(ProveError::Read(reason)) => {
104	                    eprintln!("roottrace: {reason}");
105	                    ExitCode::FAILURE
106	                }
107	                Err(ProveError::Missing(index, size)) => {
108	                    if size == 0 {
109	                        eprintln!(
110	                            "roottrace: record index {index} does not exist: the file holds zero records"
111	                        );
112	                    } else {
113	                        eprintln!(
114	                            "roottrace: record index {index} does not exist: file holds {size} record(s), valid indices are 0 through {}",
115	                            size - 1
116	                        );
117	                    }
118	                    ExitCode::FAILURE
119	                }
120	            },
121	            None => {
122	                let shown = index.to_string_lossy();
123	                eprintln!("roottrace: invalid record index '{shown}': expected a decimal non-negative integer of ASCII digits");
124	                eprintln!("{USAGE}");
125	                ExitCode::from(2)
126	            }
127	        },
128	        [cmd, proof_path] if cmd == OsStr::new("inspect") => {
129	            match inspect_file(Path::new(proof_path)) {
130	                Ok(line) => {
131	                    println!("{line}");
132	                    ExitCode::SUCCESS
133	                }
134	                Err(InspectError::Read { path, source }) => {
135	                    eprintln!(
136	                        "roottrace: cannot read '{}': {source}",
137	                        display_path(&path)
138	                    );
139	                    ExitCode::FAILURE
140	                }
141	                Err(InspectError::MalformedProof(reason)) => {
142	                    eprintln!("roottrace: invalid proof: {reason}");
143	                    ExitCode::FAILURE
144	                }
145	            }
146	        }
147	        [cmd, path, proof_path, size_arg, root_arg] if cmd == OsStr::new("verify") => {
148	            match (parse_trusted_size(size_arg), parse_trusted_root(root_arg)) {
149	                (Some(trusted_size), Some(trusted_root)) => {
150	                    match verify_files(Path::new(path), Path::new(proof_path), trusted_size, &trusted_root) {
151	                        Ok(()) => {
152	                            println!("verified");
153	                            ExitCode::SUCCESS
154	                        }
155	                        Err(VerifyError::Read { path, source }) => {
156	                            eprintln!(
157	                                "roottrace: cannot read '{}': {source}",
158	                                display_path(&path)
159	                            );
160	                            ExitCode::FAILURE
161	                        }
162	                        Err(VerifyError::MalformedProof(reason)) => {
163	                            eprintln!("roottrace: invalid proof: {reason}");
164	                            ExitCode::FAILURE
165	                        }
166	                        Err(VerifyError::Failed(reason)) => {
167	                            eprintln!("roottrace: verification failed: {reason}");
168	                            ExitCode::FAILURE
169	                        }
170	                    }
171	                }
172	                (bad_size, bad_root) => {
173	                    if bad_size.is_none() {
174	                        let shown = size_arg.to_string_lossy();
175	                        eprintln!(
176	                            "roottrace: invalid trusted tree size '{shown}': expected an ASCII decimal positive integer within unsigned 64-bit range"
177	                        );
178	                    }
179	                    if bad_root.is_none() {
180	                        let shown = root_arg.to_string_lossy();
181	                        eprintln!(
182	                            "roottrace: invalid trusted root '{shown}': expected exactly 64 lowercase hexadecimal characters"
183	                        );
184	                    }
185	                    eprintln!("{USAGE}");
186	                    ExitCode::from(2)
187	                }
188	            }
189	        }
190	        _ => {
191	            eprintln!("{USAGE}");
192	            ExitCode::from(2)
193	        }
194	    }
195	}
196	
197	enum ProveError {
198	    Read(String),
199	    Missing(u64, u64),
200	}
201	
202	/// Failures reported by `inspect`, kept separate so an unreadable proof file
203	/// and a well-readable but malformed proof both exit 1 while saying different
204	/// things on stderr.
205	enum InspectError {
206	    /// The proof path cannot be read (missing, a directory, ...).
207	    Read { path: std::path::PathBuf, source: std::io::Error },
208	    /// The proof bytes are not a well-formed proof object.
209	    MalformedProof(String),
210	}
211	
212	/// Failures reported by `verify`, kept separate so that malformed proofs and
213	/// cryptographic mismatches both exit 1 but say different things on stderr.
214	enum VerifyError {
215	    /// One of the two input paths cannot be read (missing, a directory, ...).
216	    Read { path: std::path::PathBuf, source: std::io::Error },
217	    /// The proof bytes are not a well-formed proof object.
218	    MalformedProof(String),
219	    /// The proof is well-formed but does not establish the claimed inclusion
220	    /// against the independently trusted tree size and root.
221	    Failed(String),
222	}
223	
224	/// Read the two input files and run an RFC 6962 inclusion check. The record
225	/// file's ENTIRE byte content is the target record: no LF splitting and no
226	/// trimming of trailing LF, space or CR; NUL and non-UTF-8 bytes take part as
227	/// they are. A zero-byte file is one empty record. The check itself is the
228	/// library entry point `roottrace::verify_membership`, so the command and
229	/// Rust callers of the library share exactly one verification path.
230	fn verify_files(
231	    record_path: &Path,
232	    proof_path: &Path,
233	    trusted_size: u64,
234	    trusted_root: &[u8; 32],
235	) -> Result<(), VerifyError> {
236	    let record = fs::read(record_path).map_err(|source| VerifyError::Read {
237	        path: record_path.to_path_buf(),
238	        source,
239	    })?;
240	    let proof_bytes = fs::read(proof_path).map_err(|source| VerifyError::Read {
241	        path: proof_path.to_path_buf(),
242	        source,
243	    })?;
244	    match roottrace::verify_membership(&record, &proof_bytes, trusted_size, trusted_root) {
245	        Ok(_) => Ok(()),
246	        Err(roottrace::VerifyError::MalformedProof(reason)) => {
247	            Err(VerifyError::MalformedProof(reason))
248	        }
249	        Err(roottrace::VerifyError::VerificationFailed(reason)) => Err(VerifyError::Failed(reason)),
250	        // parse_trusted_size rejects zero before this function is ever
251	        // called, so the library's invalid-argument case cannot occur here.
252	        Err(roottrace::VerifyError::InvalidTrustedSize) => {
253	            unreachable!("the command line only accepts a positive trusted tree size")
254	        }
255	    }
256	}
257	
258	/// Parse the trusted tree size given on the command line: one or more ASCII
259	/// decimal digits naming a POSITIVE 64-bit unsigned integer. Unlike a record
260	/// index, zero is not accepted (it cannot be a tree that contains a record).
261	/// Anything else (sign, whitespace, non-UTF-8 bytes, a value above u64::MAX)
262	/// is a usage error.
263	fn parse_trusted_size(arg: &OsStr) -> Option<u64> {
264	    let text = arg.to_str()?;
265	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
266	        return None;
267	    }
268	    let mut value: u64 = 0;
269	    for b in text.bytes() {
270	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
271	    }
272	    if value == 0 {
273	        return None;
274	    }
275	    Some(value)
276	}
277	
278	/// Parse the trusted root given on the command line: exactly 64 lowercase
279	/// ASCII hexadecimal characters (32 bytes). Uppercase, wrong length, non-hex
280	/// or non-UTF-8 bytes are usage errors.
281	fn parse_trusted_root(arg: &OsStr) -> Option<[u8; 32]> {
282	    let text = arg.to_str()?;
283	    if text.len() != 64 || !text.bytes().all(is_lower_hex) {
284	        return None;
285	    }
286	    let bytes = text.as_bytes();
287	    let mut out = [0u8; 32];
288	    for (i, pair) in bytes.chunks_exact(2).enumerate() {
289	        out[i] = (hex_nibble(pair[0])? << 4) | hex_nibble(pair[1])?;
290	    }
291	    Some(out)
292	}
293	
294	/// Render a path for a human-readable error message. This is used ONLY in
295	/// diagnostics: the filesystem is always given the raw `Path`, never this
296	/// lossy rendering, so a file whose name contains 0xff is not confused with a
297	/// differently named file that merely displays the same way.
298	fn display_path(path: &Path) -> String {
299	    path.to_string_lossy().into_owned()
300	}
301	
302	/// Compute the batch root by streaming the file through a fixed-size buffer.
303	/// The whole file is never held in memory: each record is hashed as its bytes
304	/// arrive (a record of any length is never stored), and the only state kept
305	/// across records is `RootStream`'s subtree stack of at most 64 hashes —
306	/// O(log n) in the record count, independent of the file's byte size and of
307	/// the longest record. The root printed for a batch is exactly the one the
308	/// previous whole-file implementation computed (and the one `prove` still
309	/// commits to), because `RootStream` folds the same RFC 6962 tree as `mth`.
310	fn merkle_root_of_file(path: &Path) -> Result<[u8; 32], String> {
311	    let mut file = fs::File::open(path)
312	        .map_err(|e| format!("cannot read '{}': {e}", display_path(path)))?;
313	    // Fixed read buffer: how many bytes one read returns cannot affect the
314	    // result — read boundaries are never record boundaries.
315	    let mut buf = [0u8; 64 * 1024];
316	    let mut stream = RootStream::new();
317	    loop {
318	        match file.read(&mut buf) {
319	            Ok(0) => break,
320	            Ok(n) => stream.feed(&buf[..n]),
321	            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
322	            // A failure partway through (including a directory path, whose
323	            // open succeeds but whose read fails) aborts the whole command:
324	            // the partial batch read so far is never reported as a root.
325	            Err(e) => return Err(format!("cannot read '{}': {e}", display_path(path))),
326	        }
327	    }
328	    Ok(stream.finish())
329	}
330	
331	fn proof_for_file(path: &Path, index: u64) -> Result<String, ProveError> {
332	    let data = fs::read(path)
333	        .map_err(|e| ProveError::Read(format!("cannot read '{}': {e}", display_path(path))))?;
334	    let records = split_records(&data);
335	    let size = records.len() as u64;
336	    if index >= size {
337	        return Err(ProveError::Missing(index, size));
338	    }
339	    let idx = index as usize;
340	    let (root, audit_path) = root_and_path(&records, idx);
341	    Ok(proof_json(size, index, &root, &audit_path))
342	}
343	
344	/// Read a proof file and return the one-line JSON object `inspect` prints:
345	/// only tree_size, leaf_index and root, taken straight from the proof. The
346	/// proof is parsed with the SAME full format check `verify` uses — a damaged
347	/// audit_path, a duplicate field, a zero tree size or an out-of-range index
348	/// are all rejected — but no target record and no trusted values exist here,
349	/// so no membership check is run and the returned text never says "verified".
350	fn inspect_file(path: &Path) -> Result<String, InspectError> {
351	    let proof_bytes = fs::read(path).map_err(|source| InspectError::Read {
352	        path: path.to_path_buf(),
353	        source,
354	    })?;
355	    let claims = match inspect_proof(&proof_bytes) {
356	        Ok(claims) => claims,
357	        Err(roottrace::InspectError::MalformedProof(reason)) => {
358	            return Err(InspectError::MalformedProof(reason));
359	        }
360	    };
361	    Ok(claims_json(&claims))
362	}
363	
364	/// Parse a record index: one or more ASCII decimal digits, non-negative, no
365	/// sign or whitespace, fitting in an unsigned 64-bit integer. Anything else
366	/// (including "+1", " 1", "1.0", "", "-1", or an argument that is not valid
367	/// UTF-8) is rejected as a usage error.
368	fn parse_index(arg: &OsStr) -> Option<u64> {
369	    let text = arg.to_str()?;
370	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
371	        return None;
372	    }
373	    let mut value: u64 = 0;
374	    for b in text.bytes() {
375	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
376	    }
377	    Some(value)
378	}
379	
380	#[cfg(test)]
381	mod tests {
382	    use super::*;
383	    use std::os::unix::ffi::OsStrExt;
384	
385	    #[test]
386	    fn index_parsing_accepts_only_ascii_unsigned_decimal() {
387	        assert_eq!(parse_index(OsStr::new("0")), Some(0));
388	        assert_eq!(parse_index(OsStr::new("00")), Some(0));
389	        assert_eq!(parse_index(OsStr::new("123")), Some(123));
390	        assert_eq!(parse_index(OsStr::new("18446744073709551615")), Some(u64::MAX));
391	        assert_eq!(parse_index(OsStr::new("18446744073709551616")), None);
392	        assert_eq!(parse_index(OsStr::new("")), None);
393	        assert_eq!(parse_index(OsStr::new("-1")), None);
394	        assert_eq!(parse_index(OsStr::new("+1")), None);
395	        assert_eq!(parse_index(OsStr::new("1.0")), None);
396	        assert_eq!(parse_index(OsStr::new(" 1")), None);
397	        assert_eq!(parse_index(OsStr::new("1 ")), None);
398	        assert_eq!(parse_index(OsStr::new("0x1")), None);
399	        assert_eq!(parse_index(OsStr::new("①")), None);
400	        // Leading-zero overflow is still overflow.
401	        assert_eq!(parse_index(OsStr::new("0018446744073709551616")), None);
402	        // An argument that is not valid UTF-8 is a usage error, never a panic.
403	        assert_eq!(parse_index(OsStr::from_bytes(b"1\xff")), None);
404	        assert_eq!(parse_index(OsStr::from_bytes(b"\xff")), None);
405	    }
406	
407	    // --- trusted command-line arguments -------------------------------------
408	
409	    #[test]
410	    fn trusted_size_accepts_only_positive_ascii_decimal_u64() {
411	        assert_eq!(parse_trusted_size(OsStr::new("1")), Some(1));
412	        assert_eq!(parse_trusted_size(OsStr::new("09")), Some(9));
413	        assert_eq!(parse_trusted_size(OsStr::new("18446744073709551615")), Some(u64::MAX));
414	        // Zero is not a tree that can contain a record.
415	        assert_eq!(parse_trusted_size(OsStr::new("0")), None);
416	        assert_eq!(parse_trusted_size(OsStr::new("00")), None);
417	        for bad in ["", "-1", "+1", "1.0", " 1", "1 ", "0x1", "18446744073709551616", "①"] {
418	            assert_eq!(parse_trusted_size(OsStr::new(bad)), None, "size {bad:?}");
419	        }
420	        assert_eq!(parse_trusted_size(OsStr::from_bytes(b"9\xff")), None);
421	    }
422	
423	    #[test]
424	    fn trusted_root_accepts_exactly_64_lowercase_hex() {
425	        let h = hex(&roottrace::mth(&[b"a"]));
426	        let parsed = parse_trusted_root(OsStr::new(&h)).expect("valid root");
427	        assert_eq!(parsed, roottrace::mth(&[b"a"]));
428	        for bad in [
429	            "",
430	            &"a".repeat(63),
431	            &"a".repeat(65),
432	            // One uppercase digit.
433	            &{
434	                let mut s = h.clone();
435	                s.replace_range(0..1, "A");
436	                s
437	            },
438	            &format!("{h} "),
439	            &format!(" {h}"),
440	            &"z".repeat(64),
441	        ] {
442	            assert!(parse_trusted_root(OsStr::new(bad)).is_none(), "root {bad:?}");
443	        }
444	        assert!(parse_trusted_root(OsStr::from_bytes(&[b'a'; 65])).is_none());
445	    }
446	}
