1	//! roottrace 库入口：为其他 Rust 程序提供 RFC 6962 成员证明（包含证明）核验。
2	//!
3	//! 命令行程序 `roottrace` 的 `root`/`prove`/`verify` 子命令同样建立在本文件的
4	//! 实现之上，因此库与命令行对同一批数据的核验结果完全一致。
5	//!
6	//! # 用法概览
7	//!
8	//! 调用方需要准备三样东西，全部在内存中，无需完整批次或临时文件：
9	//!
10	//! 1. **记录**：目标记录的全部原始字节（`&[u8]`）。每个字节都属于内容——
11	//!    空切片表示一条空记录；末尾的 LF、CR、空格、NUL 与非 UTF-8 字节都参与
12	//!    核验，不沿用批次文件的 LF 分行规则。
13	//! 2. **证明**：`roottrace prove` 输出的 JSON 证明的原始字节。字段重排、
14	//!    合法 JSON 空白与等价字符串转义按既有规则接受；重复字段、不合法的整数
15	//!    或哈希仍被拒绝。
16	//! 3. **独立确认的可信值**：树大小（`u64`，必须为正）与根值（`[u8; 32]`），
17	//!    必须来自可信渠道（签名公告、带外账本、对完整批次自行运行
18	//!    `roottrace root` 等），绝不能取自证明内部。
19	//!
20	//! 核验成功返回 [`Membership`]，可直接读取记录序号、所绑定的树大小和根值；
21	//! 返回的大小和根值就是调用方提供的可信值（已与证明核对一致），不是从证明
22	//! 里读出的字段。失败按类型区分为 [`VerifyError`] 的三个变体，库本身不向
23	//! 标准输出或标准错误打印任何内容，展示方式由调用方决定。
24	//!
25	//! 如果只想查看证明自身声明的大小、序号和根值，而没有目标记录与独立可信
26	//! 值，请改用 [`inspect_proof`]：它做同样的完整格式解读，但不做成员核验，
27	//! 其结果 [`ProofClaims`] 中的大小与根值直接来自证明、不可当作可信输入。
28	//!
29	//! # 示例
30	//!
31	//! ```
32	//! use roottrace::{verify_membership, VerifyError};
33	//!
34	//! // 只含一条空记录的批次：根值为 SHA-256(0x00)，审计路径为空。
35	//! let record: &[u8] = b"";
36	//! let proof = br#"{"tree_size":1,"leaf_index":0,"root":"6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d","audit_path":[]}"#;
37	//! let trusted_root: [u8; 32] = [
38	//!     0x6e, 0x34, 0x0b, 0x9c, 0xff, 0xb3, 0x7a, 0x98,
39	//!     0x9c, 0xa5, 0x44, 0xe6, 0xbb, 0x78, 0x0a, 0x2c,
40	//!     0x78, 0x90, 0x1d, 0x3f, 0xb3, 0x37, 0x38, 0x76,
41	//!     0x85, 0x11, 0xa3, 0x06, 0x17, 0xaf, 0xa0, 0x1d,
42	//! ];
43	//!
44	//! match verify_membership(record, proof, 1, &trusted_root) {
45	//!     Ok(m) => {
46	//!         assert_eq!(m.leaf_index(), 0);
47	//!         assert_eq!(m.tree_size(), 1);
48	//!         assert_eq!(m.root(), &trusted_root);
49	//!     }
50	//!     Err(VerifyError::MalformedProof(reason)) => {
51	//!         panic!("证明格式无效: {reason}");
52	//!     }
53	//!     Err(VerifyError::VerificationFailed(reason)) => {
54	//!         panic!("核验失败: {reason}");
55	//!     }
56	//!     Err(VerifyError::InvalidTrustedSize) => {
57	//!         panic!("可信树大小必须为正整数");
58	//!     }
59	//! }
60	//! ```
61	
62	use std::fmt;
63	
64	/// 核验成功后的类型化结果：记录在某个 Merkle 树中的成员身份已被确认。
65	///
66	/// 序号从 0 开始，指向证明声明的位置；相同内容出现在其他位置不能替代这个
67	/// 位置。树大小和根值已经与调用方的可信值核对一致——它们就是核验所锚定的
68	/// 值，而不是从证明中读出的字段。
69	#[derive(Debug, Clone, PartialEq, Eq)]
70	pub struct Membership {
71	    leaf_index: u64,
72	    tree_size: u64,
73	    root: [u8; 32],
74	}
75	
76	impl Membership {
77	    /// 被核验记录在树中的序号（从 0 开始），即证明声明的 `leaf_index`。
78	    /// 即使树大小超过平台的索引宽度，也保留完整的 64 位含义。
79	    pub fn leaf_index(&self) -> u64 {
80	        self.leaf_index
81	    }
82	
83	    /// 核验所绑定的树大小，等于调用方提供的可信树大小。
84	    pub fn tree_size(&self) -> u64 {
85	        self.tree_size
86	    }
87	
88	    /// 核验所绑定的树根值，等于调用方提供的可信根值。
89	    pub fn root(&self) -> &[u8; 32] {
90	        &self.root
91	    }
92	}
93	
94	/// 核验失败的分类，调用方可按变体区分处理方式。
95	#[derive(Debug, Clone, PartialEq, Eq)]
96	pub enum VerifyError {
97	    /// 调用参数无效：可信树大小为 0。不存在包含记录的零节点树，因此这不
98	    /// 能被当作"空树中的成员证明"接受。该判断在解读证明之前完成。
99	    InvalidTrustedSize,
100	    /// 证明格式无效：证明字节不能按现有格式解读（不是完整 JSON 对象、字段
101	    /// 缺失/重复/类型错误、整数或哈希不合法、`tree_size` 为 0、序号越界、
102	    /// 对象后有多余字节等）。附带人类可读的原因说明。
103	    MalformedProof(String),
104	    /// 核验失败：证明格式合法，但记录内容、可信树大小、可信根值或审计路径
105	    /// 不匹配。附带人类可读的原因说明。
106	    VerificationFailed(String),
107	}
108	
109	impl fmt::Display for VerifyError {
110	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
111	        match self {
112	            VerifyError::InvalidTrustedSize => {
113	                write!(f, "trusted tree size must be positive: zero cannot name a tree that holds a record")
114	            }
115	            VerifyError::MalformedProof(reason) => write!(f, "invalid proof: {reason}"),
116	            VerifyError::VerificationFailed(reason) => write!(f, "verification failed: {reason}"),
117	        }
118	    }
119	}
120	
121	impl std::error::Error for VerifyError {}
122	
123	/// 核验一条记录的 RFC 6962 成员证明，无需完整批次或临时文件。
124	///
125	/// - `record`：目标记录的全部原始字节。空切片表示一条空记录；末尾 LF、CR、
126	///   空格、NUL 与非 UTF-8 字节都属于内容，不做任何切分或修剪。
127	/// - `proof`：证明 JSON 的原始字节（如 `roottrace prove` 的输出）。字段
128	///   重排、合法空白与等价字符串转义被接受；重复字段、不合法的整数或哈希
129	///   被拒绝。
130	/// - `trusted_tree_size`：调用方**独立确认**的树大小，必须为正；为 0 时
131	///   返回 [`VerifyError::InvalidTrustedSize`]，而不是按空树核验。
132	/// - `trusted_root`：调用方**独立确认**的 32 字节根值。
133	///
134	/// 证明自带的 `tree_size` 与 `root` 只用于和可信值比对，绝不作为信任依据。
135	/// 成功时返回 [`Membership`]；失败时按 [`VerifyError`] 变体区分格式错误与
136	/// 核验失败，且不会返回任何表示已核验成功的结果。
137	pub fn verify_membership(
138	    record: &[u8],
139	    proof: &[u8],
140	    trusted_tree_size: u64,
141	    trusted_root: &[u8; 32],
142	) -> Result<Membership, VerifyError> {
143	    // 可信树大小为零是调用参数无效：必须先于证明解读拒绝，否则一份
144	    // tree_size 为 0 的"证明"会被当成空树成员证明的格式问题来报告。
145	    if trusted_tree_size == 0 {
146	        return Err(VerifyError::InvalidTrustedSize);
147	    }
148	    let proof = parse_proof(proof).map_err(VerifyError::MalformedProof)?;
149	    verify_proof(&proof, record, trusted_tree_size, trusted_root)
150	        .map_err(VerifyError::VerificationFailed)?;
151	    Ok(Membership {
152	        leaf_index: proof.leaf_index,
153	        tree_size: trusted_tree_size,
154	        root: *trusted_root,
155	    })
156	}
157	
158	/// 解读一份成员证明后、**未经任何核验**的声明值：`inspect` 操作的结果。
159	///
160	/// 与 [`Membership`] 不同，这里的树大小和根值直接来自证明自身的字段，没有
161	/// 与任何独立可信值比对，也没有目标记录可供重算路径。它们只表示“证明声称
162	/// 如此”，绝不表示记录已被证明属于该批次——即使审计路径的哈希数量、顺序或
163	/// 内容根本无法把任何记录结合到该根值，只要证明格式合法，这些字段仍会被
164	/// 原样读出。调用方不得把这里的 `tree_size()`/`root()` 当作
165	/// [`verify_membership`] 的可信输入。
166	#[derive(Debug, Clone, PartialEq, Eq)]
167	pub struct ProofClaims {
168	    tree_size: u64,
169	    leaf_index: u64,
170	    root: [u8; 32],
171	}
