245	#[doc(hidden)]
246	pub fn hex_nibble(b: u8) -> Option<u8> {
247	    match b {
248	        b'0'..=b'9' => Some(b - b'0'),
249	        b'a'..=b'f' => Some(b - b'a' + 10),
250	        _ => None,
251	    }
