254	// --- Proof parsing -----------------------------------------------------------
255	//
256	// The proof must be ONE complete JSON object. `prove` output is plain JSON,
257	// but the file may also arrive over a channel that reorders fields or changes
258	// whitespace, so both are accepted. Nothing else is: a truncated value, a
259	// duplicate key, a value of the wrong JSON type, a number that is not an
260	// exact unsigned 64-bit integer, a non-lowercase/non-64-char hash, trailing
261	// bytes after the object, or an empty file all make the proof invalid.
262	// Parsing is structural: no text decoding of the proof is required for the
263	// hashes, and integer fields are accumulated digit by digit so a value above
264	// u64::MAX (including 1e400) is rejected rather than wrapped or approximated.
265	
266	/// The fields of a well-formed inclusion proof.
267	struct Proof {
268	    tree_size: u64,
269	    leaf_index: u64,
270	    root: [u8; 32],
271	    audit_path: Vec<[u8; 32]>,
272	}
273	
274	struct ProofParser<'a> {
275	    bytes: &'a [u8],
276	    pos: usize,
277	}
278	
279	fn parse_proof(input: &[u8]) -> Result<Proof, String> {
280	    let mut p = ProofParser { bytes: input, pos: 0 };
281	    p.ws();
282	    let proof = p.parse_object().map_err(|e| e.to_string())?;
283	    p.ws();
284	    if p.pos != p.bytes.len() {
285	        return Err("trailing data after the JSON object".to_string());
286	    }
287	    let tree_size = proof.tree_size.ok_or_else(|| "missing field 'tree_size'".to_string())?;
288	    let leaf_index = proof.leaf_index.ok_or_else(|| "missing field 'leaf_index'".to_string())?;
289	    let root = proof.root.ok_or_else(|| "missing field 'root'".to_string())?;
290	    let audit_path =
291	        proof.audit_path.ok_or_else(|| "missing field 'audit_path'".to_string())?;
292	    if tree_size == 0 {
293	        return Err("tree_size must be positive".to_string());
294	    }
295	    if leaf_index >= tree_size {
296	        return Err(format!(
297	            "leaf_index {leaf_index} is out of range for tree_size {tree_size}"
298	        ));
299	    }
300	    Ok(Proof { tree_size, leaf_index, root, audit_path })
301	}
302	
303	/// Accumulator for the four recognised object members; a `Some` already
304	/// present when the same key is seen again makes the proof invalid.
305	struct ProofFields {
306	    tree_size: Option<u64>,
307	    leaf_index: Option<u64>,
308	    root: Option<[u8; 32]>,
309	    audit_path: Option<Vec<[u8; 32]>>,
310	}
311	
312	impl<'a> ProofParser<'a> {
313	    fn ws(&mut self) {
314	        while self.pos < self.bytes.len() && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r') {
315	            self.pos += 1;
316	        }
317	    }
318	
319	    fn peek(&self) -> Option<u8> {
320	        self.bytes.get(self.pos).copied()
321	    }
322	
323	    fn eat(&mut self, b: u8) -> Result<(), String> {
324	        if self.peek() == Some(b) {
325	            self.pos += 1;
326	            Ok(())
327	        } else {
328	            Err(format!("expected '{}' at byte {}", b as char, self.pos))
329	        }
330	    }
331	
332	    fn parse_object(&mut self) -> Result<ProofFields, String> {
333	        self.eat(b'{')?;
334	        let mut fields = ProofFields {
335	            tree_size: None,
336	            leaf_index: None,
337	            root: None,
338	            audit_path: None,
339	        };
340	        self.ws();
341	        if self.peek() == Some(b'}') {
342	            self.pos += 1;
343	            return Err("empty object: none of the required fields are present".to_string());
344	        }
345	        loop {
346	            self.ws();
347	            let key = self.parse_string()?;
348	            self.ws();
349	            self.eat(b':')?;
350	            self.ws();
351	            match key.as_str() {
352	                "tree_size" => {
353	                    if fields.tree_size.is_some() {
354	                        return Err("duplicate field 'tree_size'".to_string());
355	                    }
356	                    fields.tree_size = Some(self.parse_u64()?);
357	                }
358	                "leaf_index" => {
359	                    if fields.leaf_index.is_some() {
360	                        return Err("duplicate field 'leaf_index'".to_string());
361	                    }
362	                    fields.leaf_index = Some(self.parse_u64()?);
363	                }
364	                "root" => {
365	                    if fields.root.is_some() {
366	                        return Err("duplicate field 'root'".to_string());
367	                    }
368	                    fields.root = Some(self.parse_hash()?);
369	                }
370	                "audit_path" => {
371	                    if fields.audit_path.is_some() {
372	                        return Err("duplicate field 'audit_path'".to_string());
373	                    }
374	                    fields.audit_path = Some(self.parse_hash_array()?);
375	                }
376	                other => return Err(format!("unexpected field '{other}'")),
377	            }
378	            self.ws();
379	            match self.peek() {
380	                Some(b',') => {
381	                    self.pos += 1;
382	                }
383	                Some(b'}') => {
384	                    self.pos += 1;
385	                    break;
386	                }
387	                _ => return Err(format!("expected ',' or '}}' at byte {}", self.pos)),
388	            }
389	        }
390	        Ok(fields)
391	    }
392	
393	    /// A JSON string returned as UTF-8 text. Proof keys are ASCII; escapes
394	    /// (including `\uXXXX`) are decoded so a spelled-out key cannot bypass the
395	    /// recognized-name matching. Any string value anywhere is gated through
396	    /// here, so invalid escapes or an unclosed string reject the proof.
397	    fn parse_string(&mut self) -> Result<String, String> {
398	        self.eat(b'"')?;
399	        let mut out = String::new();
400	        loop {
401	            match self.peek() {
402	                None => return Err("unterminated string".to_string()),
403	                Some(b'"') => {
404	                    self.pos += 1;
405	                    break;
406	                }
407	                Some(b'\\') => {
408	                    self.pos += 1;
409	                    match self.peek() {
410	                        Some(b'"') => out.push('"'),
411	                        Some(b'\\') => out.push('\\'),
412	                        Some(b'/') => out.push('/'),
413	                        Some(b'b') => out.push('\u{0008}'),
414	                        Some(b'f') => out.push('\u{000C}'),
415	                        Some(b'n') => out.push('\n'),
416	                        Some(b'r') => out.push('\r'),
417	                        Some(b't') => out.push('\t'),
418	                        Some(b'u') => {
419	                            self.pos += 1;
420	                            let cp = self.parse_hex4()?;
421	                            // High surrogate demands a matching low surrogate.
422	                            let cp = if (0xD800..=0xDBFF).contains(&cp) {
423	                                if self.peek() != Some(b'\\') {
424	                                    return Err("lone high surrogate".to_string());
425	                                }
426	                                self.pos += 1;
427	                                if self.peek() != Some(b'u') {
428	                                    return Err("lone high surrogate".to_string());
429	                                }
430	                                self.pos += 1;
431	                                let lo = self.parse_hex4()?;
432	                                if !(0xDC00..=0xDFFF).contains(&lo) {
433	                                    return Err("high surrogate not followed by a low surrogate".to_string());
434	                                }
435	                                0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
436	                            } else if (0xDC00..=0xDFFF).contains(&cp) {
437	                                return Err("lone low surrogate".to_string());
438	                            } else {
439	                                cp
440	                            };
441	                            match char::from_u32(cp) {
442	                                Some(c) => out.push(c),
443	                                None => return Err("invalid unicode escape".to_string()),
444	                            }
445	                            continue;
446	                        }
447	                        _ => return Err("invalid escape sequence".to_string()),
448	                    }
449	                    self.pos += 1;
450	                }
451	                Some(_) => {
452	                    // Copy a run of ordinary bytes, reinterpreting the slice as
453	                    // UTF-8 for appending; control characters and invalid UTF-8
454	                    // inside a string are rejected. The run stops at ASCII
455	                    // delimiters only, so a multibyte sequence is never split.
456	                    let start = self.pos;
457	                    while self.pos < self.bytes.len() {
458	                        let b = self.bytes[self.pos];
459	                        if b == b'"' || b == b'\\' {
460	                            break;
461	                        }
462	                        if b < 0x20 {
463	                            return Err("unescaped control character in string".to_string());
464	                        }
465	                        self.pos += 1;
466	                    }
467	                    match std::str::from_utf8(&self.bytes[start..self.pos]) {
468	                        Ok(s) => out.push_str(s),
469	                        Err(_) => return Err("string is not valid UTF-8".to_string()),
470	                    }
471	                }
472	            }
473	        }
474	        Ok(out)
475	    }
476	
477	    fn parse_hex4(&mut self) -> Result<u32, String> {
478	        if self.pos + 4 > self.bytes.len() {
479	            return Err("truncated unicode escape".to_string());
480	        }
481	        let mut v = 0u32;
482	        for _ in 0..4 {
483	            let b = self.bytes[self.pos];
484	            self.pos += 1;
485	            let n = match b {
486	                b'0'..=b'9' => u32::from(b - b'0'),
487	                b'a'..=b'f' => u32::from(b - b'a' + 10),
488	                b'A'..=b'F' => u32::from(b - b'A' + 10),
489	                _ => return Err("invalid hex digit in unicode escape".to_string()),
490	            };
491	            v = (v << 4) | n;
492	        }
493	        Ok(v)
494	    }
495	
496	    /// A JSON number accepted only when it is an exact unsigned 64-bit
497	    /// integer token: digits only, no sign, fraction or exponent.
498	    fn parse_u64(&mut self) -> Result<u64, String> {
499	        let start = self.pos;
500	        while self.peek().is_some_and(|b| b.is_ascii_digit()) {
501	            self.pos += 1;
502	        }
503	        if start == self.pos {
504	            return Err("expected an unsigned integer".to_string());
505	        }
506	        // Canonical JSON integer token: "0" alone is allowed, but no leading
507	        // zeros (so "01" is rejected, not read as 1).
508	        if self.pos - start > 1 && self.bytes[start] == b'0' {
509	            return Err("integer must not have leading zeros".to_string());
510	        }
511	        if self.peek().is_some_and(|b| matches!(b, b'.' | b'e' | b'E' | b'+' | b'-')) {
512	            return Err("number must be an unsigned 64-bit integer".to_string());
513	        }
514	        let text = std::str::from_utf8(&self.bytes[start..self.pos])
515	            .map_err(|_| "integer is not ASCII".to_string())?;
516	        let mut value: u64 = 0;
517	        for b in text.bytes() {
518	            value = value
519	                .checked_mul(10)
520	                .and_then(|v| v.checked_add(u64::from(b - b'0')))
521	                .ok_or_else(|| "integer exceeds unsigned 64-bit range".to_string())?;
522	        }
523	        Ok(value)
524	    }
525	
526	    /// A JSON string that must contain exactly 64 lowercase hexadecimal
527	    /// characters, decoded to 32 bytes.
528	    fn parse_hash(&mut self) -> Result<[u8; 32], String> {
529	        let s = self.parse_string()?;
530	        if s.len() != 64 || !s.bytes().all(is_lower_hex) {
531	            return Err("hash must be a string of 64 lowercase hexadecimal characters".to_string());
532	        }
533	        let bytes = s.as_bytes();
534	        let mut out = [0u8; 32];
535	        for (i, pair) in bytes.chunks_exact(2).enumerate() {
536	            out[i] = (hex_nibble(pair[0]).unwrap() << 4) | hex_nibble(pair[1]).unwrap();
537	        }
538	        Ok(out)
539	    }
540	
541	    fn parse_hash_array(&mut self) -> Result<Vec<[u8; 32]>, String> {
542	        self.eat(b'[')?;
543	        let mut hashes = Vec::new();
544	        self.ws();
545	        if self.peek() == Some(b']') {
546	            self.pos += 1;
547	            return Ok(hashes);
548	        }
549	        loop {
550	            self.ws();
551	            hashes.push(self.parse_hash()?);
552	            self.ws();
553	            match self.peek() {
554	                Some(b',') => {
555	                    self.pos += 1;
556	                }
557	                Some(b']') => {
558	                    self.pos += 1;
559	                    break;
560	                }
561	                _ => return Err(format!("expected ',' or ']' at byte {}", self.pos)),
562	            }
563	        }
564	        Ok(hashes)
565	    }
566	}
