568	/// Check a well-formed proof against the independently trusted tree size and
569	/// root, exactly per RFC 6962 section 2.1.1:
570	///
571	/// 1. the proof's `tree_size` must equal the trusted size (the proof must not
572	///    name its own trust anchor);
573	/// 2. the proof's `root` must equal the trusted root;
574	/// 3. `leaf_index` must exist in a tree of that size (already enforced while
575	///    parsing);
576	/// 4. starting from SHA-256(0x00 || record), the audit path hashes must
577	///    recombine in the order dictated by the (possibly uneven) tree geometry
578	///    into that root, consuming every supplied hash exactly once.
579	///
580	/// Duplicate content is never searched for: the check is against the exact
581	/// `leaf_index` the proof claims. A single-record tree needs an empty path;
582	/// a path that is too short or too long for the geometry cannot succeed.
583	fn verify_proof(proof: &Proof, record: &[u8], trusted_size: u64, trusted_root: &[u8; 32]) -> Result<(), String> {
584	    if proof.tree_size != trusted_size {
585	        return Err(format!(
586	            "proof tree_size {} does not match the trusted tree size {trusted_size}",
587	            proof.tree_size
588	        ));
589	    }
590	    if proof.root != *trusted_root {
591	        return Err("proof root does not match the trusted root".to_string());
592	    }
593	    let computed = include_record(
594	        leaf_hash(record),
595	        proof.leaf_index,
596	        proof.tree_size,
597	        &proof.audit_path,
598	    )
599	    .map_err(|e| e.to_string())?;
600	    if computed != *trusted_root {
601	        return Err("record bytes or audit_path do not match the root at the claimed position".to_string());
602	    }
603	    Ok(())
604	}
605	
606	/// RFC 6962-bis recursive inclusion recomputation: the combination order is
607	/// derived from the subtree sizes, and the path is consumed in its given
608	/// leaf-to-root order. A missing sibling or an unconsumed leftover hash is an
609	/// error, so an over- or under-long path never verifies. Arithmetic stays in
610	/// u64 so sizes above `usize::MAX` cannot truncate on a 32-bit platform; the
611	/// recursion depth is bounded by the hashes actually present in the path.
612	fn include_record(
613	    leaf: [u8; 32],
614	    m: u64,
615	    n: u64,
616	    path: &[[u8; 32]],
617	) -> Result<[u8; 32], String> {
618	    fn sub(
619	        leaf: [u8; 32],
620	        m: u64,
621	        n: u64,
622	        path: &[[u8; 32]],
623	        pos: &mut usize,
624	    ) -> Result<[u8; 32], String> {
625	        if n == 1 {
626	            return Ok(leaf);
627	        }
628	        // Largest power of two strictly smaller than n.
629	        let k = 1u64 << (u64::BITS - 1 - (n - 1).leading_zeros());
630	        if m < k {
631	            let left = sub(leaf, m, k, path, pos)?;
632	            let right = take(path, pos)?;
633	            Ok(node_hash(&left, &right))
634	        } else {
635	            let right = sub(leaf, m - k, n - k, path, pos)?;
636	            let left = take(path, pos)?;
637	            Ok(node_hash(&left, &right))
638	        }
639	    }
640	    fn take(path: &[[u8; 32]], pos: &mut usize) -> Result<[u8; 32], String> {
641	        let h = *path
642	            .get(*pos)
643	            .ok_or_else(|| "audit_path is shorter than the tree requires".to_string())?;
644	        *pos += 1;
645	        Ok(h)
646	    }
647	    let mut pos = 0;
648	    let root = sub(leaf, m, n, path, &mut pos)?;
649	    if pos != path.len() {
650	        return Err("audit_path is longer than the tree requires".to_string());
651	    }
652	    Ok(root)
653	}
