687	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
688	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
689	    let mut h = Sha256::new();
690	    h.update(&[0x01]);
691	    h.update(left);
692	    h.update(right);
693	    h.finalize()
