767	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256: the batch root, built
768	/// by the shared `build_tree` constructor so it follows exactly the same
769	/// rules as proof generation.
770	#[doc(hidden)]
771	pub fn mth(leaves: &[&[u8]]) -> [u8; 32] {
772	    build_tree(leaves, None, &mut Vec::new())
773	}
