775	/// RFC 6962 section 2.1.1: the Merkle Tree Hash of the whole batch together
776	/// with the Merkle Audit Path for the record at `m`, both produced by the
777	/// shared `build_tree` constructor. The returned path is ordered from the
778	/// leaf level up to the root and is empty for a batch of exactly one record.
779	#[doc(hidden)]
780	pub fn root_and_path(leaves: &[&[u8]], m: usize) -> ([u8; 32], Vec<[u8; 32]>) {
781	    let n = leaves.len();
782	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
783	    let mut path = Vec::new();
784	    let root = build_tree(leaves, Some(m), &mut path);
785	    (root, path)
786	}
