1504	        assert!(parse_proof(&full).is_ok());
1505	
1506	        let drop_field = |bytes: &[u8], needle: &str| -> Vec<u8> {
1507	            let text = String::from_utf8(bytes.to_vec()).unwrap();
1508	            // Rebuild without the named member by string surgery on the
1509	            // canonical compact form emitted by proof_json.
1510	            let idx = text.find(needle).unwrap();
1511	            let mut end = idx + needle.len();
1512	            // Consume through the member's value terminator.
1513	            match needle {
1514	                "\"tree_size\":" | "\"leaf_index\":" => {
1515	                    while end < text.len()
1516	                        && text.as_bytes()[end] != b','
1517	                        && text.as_bytes()[end] != b'}'
1518	                    {
1519	                        end += 1;
1520	                    }
1521	                }
1522	                "\"root\":" => {
1523	                    while end < text.len() && text.as_bytes()[end] != b'"' {
1524	                        end += 1;
1525	                    }
1526	                    end += 1;
1527	                }
1528	                _ => {
1529	                    end = text.rfind(']').unwrap() + 1;
1530	                }
1531	            }
1532	            let mut s = String::new();
1533	            s.push_str(&text[..idx]);
1534	            let rest = &text[end..];
1535	            // Tidy the separator left by the removed member.
1536	            if rest.starts_with(',') {
1537	                s.push_str(&rest[1..]);
1538	            } else if text[..idx].ends_with(',') {
1539	                s.pop();
1540	                s.push_str(rest);
1541	            } else {
1542	                s.push_str(rest);
1543	            }
1544	            s.into_bytes()
1545	        };
1546	
1547	        for key in ["\"tree_size\":", "\"leaf_index\":", "\"root\":", "\"audit_path\":"] {
1548	            let cut = drop_field(&full, key);
1549	            assert!(parse_proof(&cut).is_err(), "proof missing {key} must be invalid: {cut:?}");
1550	        }
1551	
1552	        for bad in [
1553	            b"".as_slice(),
1554	            b"   ",
1555	            b"null",
1556	            b"[]",
1557	            b"\"x\"",
1558	            b"123",
