            "{{\"tree_siz\\u0065\":2,\"leaf_index\":1,\"root\":\"{h}\",\"audit_path\":[\"{p0}\"]}}"
        );
        assert!(verify_membership(b"b", escaped.as_bytes(), 2, &root).is_ok());
