/// Receives the division of a byte stream into records from
/// [`RecordScanner`]. Every method sees raw bytes only.
trait RecordSink {
    /// A run of content bytes belonging to the record currently in progress;
    /// the slice is borrowed from the chunk being scanned and must not be
    /// relied on after the call returns. A long record is delivered as any
    /// number of consecutive runs spanning any number of chunks.
    fn record_bytes(&mut self, bytes: &[u8]);

    /// The record in progress has been terminated by an LF (which is not
    /// delivered as content), including an empty one after a leading or
    /// consecutive LF.
    fn record_end(&mut self);

    /// The stream ended. A record that received content but no terminating LF
    /// is completed exactly as if it had one; a bare trailing LF has already
    /// ended its record and adds nothing here.
    fn stream_end(&mut self);
}

/// The shared record-boundary state machine. Independent of how the bytes are
/// obtained: one whole batch ([`RecordScanner::scan`]) or arbitrarily sized
/// chunks fed across reads ([`RecordScanner::feed`]) divide into exactly the
/// same record sequence.
struct RecordScanner<S: RecordSink> {
    sink: S,
}

impl<S: RecordSink> RecordScanner<S> {
    fn new(sink: S) -> Self {
        RecordScanner { sink }
    }

    /// Feed the next chunk. Read boundaries fall inside content or on LF
    /// bytes; either way the division sees no boundary of its own — an LF split
    /// across two chunks still ends the record, and two LFs in adjacent chunks
    /// keep the empty record between them.
    fn feed(&mut self, chunk: &[u8]) {
        let mut rest = chunk;
        while let Some(pos) = rest.iter().position(|&b| b == b'\n') {
            self.sink.record_bytes(&rest[..pos]);
            self.sink.record_end();
            rest = &rest[pos + 1..];
        }
        self.sink.record_bytes(rest);
    }

    /// Finish the stream and give back the sink.
    fn finish(self) -> S {
        let mut sink = self.sink;
        sink.stream_end();
        sink
    }

    /// Convenience for callers that already hold the whole input: divide it in
    /// one pass.
    fn scan(mut self, data: &[u8]) -> S {
        self.feed(data);
        self.finish()
    }
}

